(()=>{$.get("https://students-api.up.railway.app/movies",(e=>{r(e)}));const e=document.querySelector("#card-container"),r=r=>{r.forEach((r=>{const t=document.createElement("div");t.classList.add("card","mb-3","col-sm-6"),t.innerHTML=`\n            <img src="${r.poster}" class="card-img-top" alt="${r.title} Poster">\n            <div class="card-body">\n                <a href="#"><h5 class="card-title">${r.title}</h5></a>\n                <p class="card-text">Year: ${r.year}<br>\n                Director: ${r.director}<br>\n                Duration: ${r.duration}<br>\n                Genre: ${r.genre.join(", ")}<br>\n                Rate: ${r.rate}</p>\n            </div>\n        `,e.appendChild(t)}))}})();